import time
import logging


class TimeoutException(Exception):
    pass


def wait_until_keyword_succeeds(timeout, interval, func):
    end = timeout + time.time()
    result = None
    ok = False
    while not ok and time.time() < end:
        try:
            result = func()
            ok = True
        except Exception as e:
            logging.warning(str(e))
            time.sleep(interval)
    if not ok:
        raise TimeoutException()
    return result
